package com.shlapak.yaroslav.leetcode.problems.p0030

import com.shlapak.yaroslav.leetcode.support.asString
import io.kotest.matchers.shouldBe
import io.kotest.core.spec.style.FreeSpec
import kotlin.time.Duration.Companion.seconds

/**
 * Tests [SubstringWithConcatenationOfAllWords],
 * [SubstringWithConcatenationOfAllWordsAlternative2].
 */
class SubstringWithConcatenationOfAllWordsTest : FreeSpec({
    "findSubstring" - {
        val inputs = getInputs()
        inputs.asSequence().forEach { (input, expected) ->
            "input.s: ${input.s.asString()}, input.words: ${input.words.toList().asString()} expected: ${expected.asString()}"
                    .config(timeout = 2.seconds) {
                        val actual = SubstringWithConcatenationOfAllWords().findSubstring(input.s, input.words)
                        println("actual:   $actual")
                        println("expected: $expected")
                        actual.sorted() shouldBe expected
                    }
        }
    }

    "findSubstring2" - {
        val inputs = getInputs()
        inputs.asSequence().forEach { (input, expected) ->
            "input.s: ${input.s.asString()}, input.words: ${input.words.toList().asString()} expected: ${expected.asString()}"
                    .config(timeout = 2.seconds, enabled = false) {
                        val actual = SubstringWithConcatenationOfAllWordsAlternative2().findSubstring(input.s, input.words)
                        println("actual:   $actual")
                        println("expected: $expected")
                        actual.sorted() shouldBe expected
                    }
        }
    }
}) {
    data class Parameter(
            val s: String,
            val words: Array<String>
    ) {
        override fun equals(other: Any?): Boolean {
            if (this === other) return true
            if (other !is Parameter) return false

            if (s != other.s) return false
            if (!words.contentEquals(other.words)) return false

            return true
        }

        override fun hashCode(): Int {
            var result = s.hashCode()
            result = 31 * result + words.contentHashCode()
            return result
        }
    }
}

